claims.exact_check_output:
@Allow.ContextCleanup.receipt_proves_matching_cleanup : ∀ {durable : Nat} {s : Allow.ContextCleanup.Lease}
  {r : Allow.ContextCleanup.Receipt},
  Allow.ContextCleanup.Reachable durable s →
    Eq.{1} s.receipt (some.{0} r) →
      Eq.{1} r.owner s.owner ∧ Allow.ContextCleanup.CleanupSafe s ∧ Eq.{1} r.successPermitted !s.poisoned

@Allow.ContextCleanup.reachable_clean_has_receipt : ∀ {durable : Nat} {s : Allow.ContextCleanup.Lease},
  Allow.ContextCleanup.Reachable durable s →
    Eq.{1} s.phase Allow.ContextCleanup.Phase.clean → Exists.{1} fun r => Eq.{1} s.receipt (some.{0} r)

@Allow.ContextCleanup.reachable_clean_is_safe : ∀ {durable : Nat} {s : Allow.ContextCleanup.Lease},
  Allow.ContextCleanup.Reachable durable s →
    Eq.{1} s.phase Allow.ContextCleanup.Phase.clean → Allow.ContextCleanup.CleanupSafe s

@Allow.ContextCleanup.release_requires_clean : ∀ {s t : Allow.ContextCleanup.Lease},
  Allow.ContextCleanup.Step s t →
    Eq.{1} t.phase Allow.ContextCleanup.Phase.vacant → Eq.{1} s.phase Allow.ContextCleanup.Phase.clean

@Allow.ContextCleanup.replacement_requires_vacant : ∀ {s t : Allow.ContextCleanup.Lease},
  Allow.ContextCleanup.Step s t →
    Eq.{1} t.phase Allow.ContextCleanup.Phase.reserved → Eq.{1} s.phase Allow.ContextCleanup.Phase.vacant

@Allow.ContextCleanup.unknown_cannot_be_replaced : ∀ {s t : Allow.ContextCleanup.Lease},
  Allow.ContextCleanup.Step s t →
    Eq.{1} s.phase Allow.ContextCleanup.Phase.unknown → Ne.{1} t.phase Allow.ContextCleanup.Phase.reserved

@Allow.ContextCleanup.accepted_receipt_exact_owner : ∀ {expected : Allow.ContextCleanup.Owner}
  {r : Allow.ContextCleanup.Receipt},
  Eq.{1} (Allow.ContextCleanup.acceptReceipt expected r) true → Eq.{1} r.owner expected

@Allow.ContextCleanup.context_ok_requires_cleanup : ∀ {durable : Nat} {s : Allow.ContextCleanup.Lease}
  {r : Allow.ContextCleanup.Receipt},
  Allow.ContextCleanup.Reachable durable s → Allow.ContextCleanup.contextOK s r → Allow.ContextCleanup.CleanupSafe s

@Allow.ContextCleanup.context_ok_requires_staged_unpoisoned_success : ∀ {s : Allow.ContextCleanup.Lease}
  {r : Allow.ContextCleanup.Receipt},
  Allow.ContextCleanup.contextOK s r → Eq.{1} s.staged true ∧ Eq.{1} r.successPermitted true ∧ Eq.{1} s.poisoned false

Allow.ContextCleanup.normal_cleanup_witness : Allow.ContextCleanup.Reachable 42 Allow.ContextCleanup.w10 ∧
  Allow.ContextCleanup.contextOK Allow.ContextCleanup.w10
    { owner := Allow.ContextCleanup.witnessOwner, successPermitted := true }
